const raw = ($('Merge Job Data').item.json.output ?? '').trim();

function esc(s) {
  return String(s ?? '')
    .replace(/\\/g,  '\\\\textbackslash{}')
    .replace(/&/g,   '\\\\&')
    .replace(/%/g,   '\\\\%')
    .replace(/\$/g,  '\\\\$')
    .replace(/#/g,   '\\\\#')
    .replace(/_/g,   '\\\\_')
    .replace(/\{/g,  '\\\\{')
    .replace(/\}/g,  '\\\\}')
    .replace(/~/g,   '\\\\textasciitilde{}')
    .replace(/\^/g,  '\\\\textasciicircum{}');
}

function parseResumeRobust(raw) {
  const lines = raw.split('\n').map(line => line.trim());

  const sectionHeaders = [
    { key: 'SUMMARY', keywords: ['SUMMARY', 'PROFESSIONAL SUMMARY', 'CAREER SUMMARY', 'OBJECTIVE'] },
    { key: 'EXPERIENCE', keywords: ['PROFESSIONAL EXPERIENCE', 'EXPERIENCE', 'WORK EXPERIENCE'] },
    { key: 'EDUCATION', keywords: ['EDUCATION'] },
    { key: 'SKILLS', keywords: ['SKILLS', 'TECHNICAL SKILLS'] },
    { key: 'PROJECTS', keywords: ['PROJECTS', 'TECHNICAL PROJECTS', 'KEY PROJECTS'] },
    { key: 'CERTIFICATIONS', keywords: ['CERTIFICATIONS', 'ADDITIONAL INFORMATION'] }
  ];

  const sectionLines = {};
  for (let idx = 0; idx < lines.length; idx++) {
    const line = lines[idx];
    const lineUpper = line.toUpperCase().replace(':', '').trim();
    for (const sec of sectionHeaders) {
      if (sec.keywords.includes(lineUpper)) {
        sectionLines[sec.key] = idx;
        break;
      }
    }
  }

  const sortedSecs = Object.entries(sectionLines).sort((a, b) => a[1] - b[1]);
  const sections = {};
  for (let i = 0; i < sortedSecs.length; i++) {
    const [key, startIdx] = sortedSecs[i];
    const endIdx = i + 1 < sortedSecs.length ? sortedSecs[i+1][1] : lines.length;
    sections[key] = lines.slice(startIdx + 1, endIdx);
  }

  // Fallbacks if section splitting failed
  for (const sec of sectionHeaders) {
    if (!sections[sec.key]) {
      sections[sec.key] = [];
    }
  }

  const summaryText = sections.SUMMARY.join(' ').trim();
  const skillsText = sections.SKILLS.join('\n').trim();
  const eduText = sections.EDUCATION.join('\n').trim();
  const expText = sections.EXPERIENCE.join('\n').trim();

  return {
    firstName: "Satish Kumar",
    lastName: "Tripathy",
    email: "skt23122004@gmail.com",
    phone: "+91 9508829892",
    linkedin: "satish-tripathy-64755522b",
    github: "anonymous23122004",
    city: "Bhubaneswar, Odisha, India",
    summaryText,
    skillsText,
    eduText,
    expText
  };
}

function parseExperience(text) {
  if (!text) return '';
  const lines = text.split('\n').map(l => l.trim()).filter(Boolean);
  const entries = [];
  let currentEntry = null;

  for (const line of lines) {
    if (line.startsWith('-') || line.startsWith('*') || line.startsWith('•')) {
      if (currentEntry) {
        currentEntry.bullets.push(line.replace(/^[-\*•]\s*/, ''));
      }
    } else {
      let title = "";
      let company = "";
      let dates = "";
      let location = "Remote";

      const parts = (line.includes('|') ? line.split('|') : line.split(/\s{2,}/))
        .map(s => s.trim())
        .filter(Boolean);

      const dateRegex = /(?:jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)[a-z]*\s*\d{4}|\d{4}\s*[-–—]\s*(?:\d{4}|present|current)/i;
      const locRegex = /remote|on site|on-site|hybrid|bhubaneswar|odisha|india|confidential/i;

      let remainingParts = [];
      for (const part of parts) {
        if (dateRegex.test(part)) {
          dates = part;
        } else if (locRegex.test(part) && !/engineer|designer|developer|manager/i.test(part)) {
          location = part;
        } else {
          remainingParts.push(part);
        }
      }

      if (!dates) {
        const dateMatch = line.match(dateRegex);
        if (dateMatch) dates = dateMatch[0];
      }

      if (!location) {
        const locMatch = line.match(locRegex);
        if (locMatch && !/engineer|designer|developer|manager/i.test(locMatch[0])) location = locMatch[0];
      }

      if (remainingParts.length >= 2) {
        title = remainingParts[0];
        company = remainingParts[1];
      } else if (remainingParts.length === 1) {
        title = remainingParts[0];
      }

      const parenLocMatch = title.match(/\((remote|on site|on-site|hybrid)\)/i);
      if (parenLocMatch) {
        location = parenLocMatch[1];
        title = title.replace(/\((remote|on site|on-site|hybrid)\)/i, '').trim();
      }

      const cleanTitleKeywords = ["Software Engineer Intern", "Software Engineer", "UI Designer", "UI/UX Designer", "Member of Technical Staff", "Senior AI Engineer", "AI Engineer"];
      for (const kw of cleanTitleKeywords) {
        if (title.toLowerCase().startsWith(kw.toLowerCase())) {
          const remaining = title.slice(kw.length).trim();
          if (remaining.length > 3) {
            company = remaining.replace(/^(?:at|@|for|in)\s+/i, '');
            title = kw;
          }
          break;
        }
      }

      const prevHasTitleKeywords = currentEntry ? /engineer|designer|developer|manager|intern|staff|member/i.test(currentEntry.title) : false;

      if (currentEntry && currentEntry.bullets.length === 0 && !prevHasTitleKeywords) {
        company = title;
        title = currentEntry.title;
        if (currentEntry.dates && !dates) dates = currentEntry.dates;
        if (currentEntry.location !== "Remote" && location === "Remote") location = currentEntry.location;

        currentEntry = {
          title: company || "Software Engineer",
          company: title || "Company",
          dates: dates || "",
          location: location || "Remote",
          bullets: []
        };
      } else {
        if (currentEntry) {
          entries.push(currentEntry);
        }

        currentEntry = {
          title: title || "Software Engineer",
          company: company || "Company",
          dates: dates || "",
          location: location || "Remote",
          bullets: []
        };
      }
    }
  }

  if (currentEntry) {
    entries.push(currentEntry);
  }

  let out = '\\resumeSubHeadingListStart\n';
  for (const entry of entries) {
    entry.company = entry.company.replace(/^[,\s\-:|]+|[,\s\-:|]+$/g, '').trim();
    entry.title = entry.title.replace(/^[,\s\-:|]+|[,\s\-:|]+$/g, '').trim();

    out += `  \\resumeSubheading\n    {${esc(entry.title)}}{${esc(entry.dates)}}\n    {${esc(entry.company)}}{${esc(entry.location)}}\n`;
    if (entry.bullets.length) {
      out += '  \\resumeItemListStart\n';
      for (const b of entry.bullets) {
        out += `    \\resumeItem{${esc(b)}}\n`;
      }
      out += '  \\resumeItemListEnd\n';
    }
  }
  out += '\\resumeSubHeadingListEnd\n';
  return out;
}

function parseEducation(text) {
  if (!text) return '';
  const lines = text.split('\n').map(l => l.trim()).filter(Boolean);
  const entries = [];
  let currentEntry = null;

  for (const line of lines) {
    if (line.startsWith('-') || line.startsWith('*') || line.startsWith('•')) {
      if (currentEntry) {
        currentEntry.bullets.push(line.replace(/^[-\*•]\s*/, ''));
      }
    } else {
      if (currentEntry) {
        entries.push(currentEntry);
      }
      currentEntry = {
        degree: "",
        school: "",
        dates: "",
        location: "Bhubaneswar, Odisha, India",
        bullets: []
      };

      const parts = line.split(/[|]/).map(s => s.trim()).filter(Boolean);
      let school = "";
      let degree = "";
      let dates = "";

      const dateRegex = /\d{4}\s*[-–—]\s*(?:\d{4}|present)/i;
      const degRegex = /b\.tech|bachelor|m\.tech|master|diploma|hsc|ssc|csec|high school/i;

      let remaining = [];
      for (const part of parts) {
        if (dateRegex.test(part)) {
          dates = part;
        } else if (degRegex.test(part)) {
          degree = part;
        } else {
          remaining.push(part);
        }
      }

      if (!dates) {
        const dateMatch = line.match(dateRegex);
        if (dateMatch) dates = dateMatch[0];
      }

      if (!degree) {
        const degMatch = line.match(degRegex);
        if (degMatch) degree = degMatch[0];
      }

      if (remaining.length >= 2) {
        school = remaining[0];
        if (!degree) degree = remaining[1];
      } else if (remaining.length === 1) {
        school = remaining[0];
      }

      currentEntry.school = school || "GITA Autonomous College";
      currentEntry.degree = degree || "B.Tech in Computer Science";
      currentEntry.dates = dates || "2022 - 2026";
    }
  }

  if (currentEntry) {
    entries.push(currentEntry);
  }

  let out = '\\resumeSubHeadingListStart\n';
  for (const entry of entries) {
    out += `  \\resumeSubheading\n    {${esc(entry.degree)}}{${esc(entry.dates)}}\n    {${esc(entry.school)}}{${esc(entry.location)}}\n`;
    if (entry.bullets.length) {
      out += '  \\resumeItemListStart\n';
      for (const b of entry.bullets) {
        out += `    \\resumeItem{${esc(b)}}\n`;
      }
      out += '  \\resumeItemListEnd\n';
    }
  }
  out += '\\resumeSubHeadingListEnd\n';
  return out;
}

function parseSkills(text) {
  if (!text) return '';
  const lines = text.split('\n').map(l => l.trim()).filter(Boolean);
  let out = '\\begin{itemize}[leftmargin=0.15in, label={}]\n  \\small{\\item{\n';
  for (const line of lines) {
    const clean = line.replace(/^[-\*•]\s*/, '');
    const ci = clean.indexOf(':');
    if (ci > 0) {
      out += `    \\textbf{${esc(clean.slice(0, ci).trim())}}{: ${esc(clean.slice(ci + 1).trim())}} \\\\
`;
    } else {
      out += `    ${esc(clean)} \\\\
`;
    }
  }
  out += '  }}\n\\end{itemize}\n';
  return out;
}

